import {modelFor,transactionCosts,maxAffordableQuantity,LEGACY_COST_MODEL,TAX_CORRECTION_COST_VERSION} from './costs.js?v=preview-v11';
export function fresh(s){const state={index:0,cash:s.initialCash,shares:0,fees:0,receivable:0,dividends:0,claims:[],splitEvents:[],journal:[],equity:[s.initialCash],finished:false};if(modelFor(s).version!==LEGACY_COST_MODEL.version){state.taxes=0;state.totalCosts=0;}return state;}
export function mark(s,state){return state.finished?s.rounds[state.index].close:s.rounds[state.index].price;}
export function visible(s,state){const r=s.rounds[state.index],cutoff=state.finished?r.revealAt:r.at;let bars=[...(s.history??[]),...s.rounds.slice(0,state.index+(state.finished?1:0)).map(x=>x.bar)].filter(Boolean);const adjustmentDate=(state.finished?r.bar?.date:r.at.slice(0,10));const knownSplits=(s.corporateActions??[]).filter(a=>a.type==='split'&&(a.effectiveDate??a.exDate)<=adjustmentDate);bars=bars.map(b=>{const factor=knownSplits.filter(a=>b.date<(a.effectiveDate??a.exDate)).reduce((f,a)=>f*a.ratio,1);return {...b,rawOpen:b.open,rawHigh:b.high,rawLow:b.low,rawClose:b.close,open:b.open/factor,high:b.high/factor,low:b.low/factor,close:b.close/factor,comparableVolume:b.volume*factor,splitFactor:factor};});const prices=bars.length?bars.map(b=>({at:b.closeAt,price:b.close})):s.rounds.slice(0,state.index+1).map(x=>({at:x.priceAt,price:x.price}));if(!bars.length&&state.finished)prices.push({at:r.closeAt,price:r.close});const news=[...new Map([...(s.news??[]),...s.rounds.flatMap(x=>x.news)].filter(n=>typeof(n.availableAt??n.publishedAt)==='string'&&(n.availableAt??n.publishedAt)<=cutoff).map(n=>[n.id,n])).values()].sort((a,b)=>(b.availableAt??b.publishedAt).localeCompare(a.availableAt??a.publishedAt));return {cutoff,bars,prices,news};}
export function wealth(s,state){return state.cash+state.shares*mark(s,state)+(state.receivable??0);}
export function benchmark(s,state){if(!state.journal.length)return s.initialCash;const p=s.rounds[0].executionPrice,initialQ=maxAffordableQuantity(s,s.initialCash,p);let q=initialQ,dividends=0;const end=state.finished?state.index:state.index;for(let i=1;i<=end;i++){const r=s.rounds[i];q*=r.splitRatio??1;if(i<state.journal.length){for(const a of s.corporateActions??[]){if(a.type!=='split'&&a.exDate===r.at.slice(0,10))dividends+=q*a.cashPerUnit;}}}const cost=transactionCosts(s,'buy',initialQ,p),spent=[LEGACY_COST_MODEL.version,TAX_CORRECTION_COST_VERSION].includes(modelFor(s).version)?initialQ*p*(1+modelFor(s).feeRate):-cost.cashFlow;return s.initialCash-spent+q*mark(s,state)+dividends;}
export function decide(s,state,side,quantity,reason){const costModel=modelFor(s),isLegacy=costModel.version===LEGACY_COST_MODEL.version,preservedCommission=isLegacy||costModel.version===TAX_CORRECTION_COST_VERSION,tolerance=isLegacy?1e-8:0;if(state.finished)throw Error('本回合已結束，請重新開始。');if(!['buy','sell','hold'].includes(side))throw Error('無效的決策。');if(!reason.trim())throw Error('請寫下你的判斷依據，再前往下一期。');if(side!=='hold'&&(!Number.isSafeInteger(quantity)||quantity<=0))throw Error('請輸入大於 0 的整數單位。');if(side==='sell'&&quantity>state.shares)throw Error('持有單位不足，無法放空。');if(side==='buy'&&(preservedCommission?quantity*s.rounds[state.index].price*(1+costModel.feeRate):-transactionCosts(s,'buy',quantity,s.rounds[state.index].price).cashFlow)>state.cash+tolerance)throw Error('依昨收估算可用現金不足，請降低買入單位。');if(side==='sell'&&state.cash+transactionCosts(s,'sell',quantity,s.rounds[state.index].price).cashFlow < -tolerance)throw Error('依昨收估算現金不足支付賣出費稅，請調整單位或觀望。');const n=structuredClone(state),r=s.rounds[n.index];for(const a of s.corporateActions??[]){if(a.type!=='split'&&a.exDate===r.at.slice(0,10)&&n.shares>0){const amount=n.shares*a.cashPerUnit;n.claims.push({exDate:a.exDate,paymentDate:a.paymentDate,amount,paid:false});n.receivable+=amount;n.dividends+=amount;}}let q=side==='hold'?0:quantity,cost=transactionCosts(s,side,q,r.executionPrice),{amount,fee,tax}=cost,status=side==='hold'?'held':'filled';if(side==='buy'&&amount+fee>n.cash+tolerance||side==='sell'&&n.cash+cost.cashFlow < -tolerance){q=0;cost=transactionCosts(s,side,0,r.executionPrice);amount=0;fee=0;tax=0;status='cancelled';}if(side==='buy'){n.cash-=amount+fee;n.shares+=q;}if(side==='sell'){n.cash+=isLegacy?amount-fee:cost.cashFlow;n.shares-=q;}n.fees+=fee;const modern=modelFor(s).version!==LEGACY_COST_MODEL.version;if(modern){n.taxes+=tax;n.totalCosts+=fee+tax;}n.journal.push({at:r.at,executionAt:r.executionAt,side,requestedQuantity:side==='hold'?0:quantity,quantity:q,price:r.executionPrice,close:r.close,fee,status,reason:reason.trim(),cash:n.cash,shares:n.shares,newsIds:visible(s,n).news.map(x=>x.id),...(modern?{tax,totalCost:fee+tax,costModelVersion:modelFor(s).version,...(status==='cancelled'?{cancelReason:'insufficient-cash-at-open'}:{})}:{})});n.equity.push(n.cash+n.shares*r.close+(n.receivable??0));if(n.index<s.rounds.length-1){n.index++;const next=s.rounds[n.index];if((next.splitRatio??1)!==1){n.shares*=next.splitRatio;n.splitEvents.push({date:next.at.slice(0,10),ratio:next.splitRatio});}}else n.finished=true;const cutoff=(n.finished?r.revealAt:s.rounds[n.index].at)?.slice(0,10);for(const claim of n.claims??[]){if(!claim.paid&&claim.paymentDate<=cutoff){claim.paid=true;n.cash+=claim.amount;n.receivable-=claim.amount;}}return n;}
